ssn": ["0027-8424", "1091-6490"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "cwts-core", "dongbi-a", "doyens", "erih-plus", "jufo-3", "ki-jl-3", "medline", "norway-2", "poland-200", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310320052", "host_organization_name": "National Academy of Sciences", "host_organization_lineage": ["https://openalex.org/P4310320052"], "host_organization_lineage_names": ["National Academy of Sciences"], "type": "journal"}, "license": "cc-by-nc-nd", "license_id": "https://openalex.org/licenses/cc-by-nc-nd", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Proceedings of the National Academy of Sciences", "raw_type": "journal-article"}, "abstract": "An RNA polymerase ribozyme that was obtained by directed evolution can propagate a functional RNA through repeated rounds of replication and selection, thereby enabling Darwinian evolution. Earlier versions of the polymerase did not have sufficient copying fidelity to propagate functional information, but a new variant with improved fidelity can replicate the hammerhead ribozyme through reciprocal synthesis of both the hammerhead and its complement, with the products then being selected for RNA-cleavage activity. Two evolutionary lineages were carried out in parallel, using either the prior low-fidelity or the newer high-fidelity polymerase. The former lineage quickly lost hammerhead functionality as the population diverged toward random sequences, whereas the latter evolved new hammerhead variants with improved fitness compared to the starting RNA. The increase in fitness was attributable to specific mutations that improved the replicability of the hammerhead, counterbalanced by a small decrease in hammerhead activity. Deep sequencing analysis was used to follow the course of evolution, revealing the emergence of a succession of variants that progressively diverged from the starting hammerhead as fitness increased. This study demonstrates the critical importance of replication fidelity for maintaining heritable information in an RNA-based evolving system, such as is thought to have existed during the early history of life on Earth. Attempts to recreate RNA-based life in the laboratory must achieve further improvements in replication fidelity to enable the fully autonomous Darwinian evolution of RNA enzymes as complex as the polymerase itself."}]", "excerpt_truncated": true, "source_sha256": "5c0b50e5ffbba590ea94253843d414157c6910ca1e18908133d4f4a8bac16418", "verification_required": true, "topic_domain": "chemical_heredity", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.3390/life11040308", "openalex:W3144837547"], "source_candidates": ["https://doi.org/10.3390/life11040308"], "source_candidate_identities": {}}

